import React from 'react';
import ProductCard from '../components/ProductCard';

const Home = ({ onNavigate }) => { // ✅ Добавьте onNavigate в пропсы
  const featuredProducts = [
    {
      id: 1,
      name: "Серьги Лунное сияние", 
      price: 12500,
      image: "https://via.placeholder.com/400x400/4A5568/FFFFFF?text=Серьги+Луна",
      description: "Элегантные серьги ручной работы",
      material: "Серебро 925",
      category: "earrings",
      collection: "luna"
    },
    {
      id: 2,
      name: "Кольцо Звездная пыль",
      price: 8900, 
      image: "https://via.placeholder.com/400x400/2D3748/FFFFFF?text=Кольцо+Звезда",
      description: "Изящное кольцо с фианитами",
      material: "Серебро 925",
      category: "rings", 
      collection: "solaris"
    }
  ];

  return (
    <div>
      {/* Hero Section */}
      <section className="relative h-96 flex items-center justify-center">
        <div className="text-center">
          <h1 className="text-4xl md:text-6xl font-serif font-bold mb-4">LUNA AUREA</h1>
        </div>
      </section>

      {/* Featured Products */}
      <section className="py-16">
        <div className="max-w-7xl mx-auto px-4">
          <h2 className="text-3xl font-serif font-bold text-center mb-12">Популярные товары</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {featuredProducts.map((product) => (
              <ProductCard 
                key={product.id} 
                product={product} 
                onNavigate={onNavigate} // ✅ Передаем onNavigate
              />
            ))}
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
